export interface Worker { stop(): Promise<void>; }
export interface Registry {
  get(id: string): Worker | undefined;
  remove(id: string): void;
  add(id: string, w: Worker): void;
}

export async function updateWorker(reg: Registry, id: string, config: { poolSize: number }, create: (c: { poolSize: number }) => Worker): Promise<void> {
  const existing = reg.get(id);
  if (existing) {
    await existing.stop();
    reg.remove(id);
  }
  if (!Number.isInteger(config.poolSize) || config.poolSize < 1) {
    throw new Error("invalid poolSize: " + config.poolSize);
  }
  reg.add(id, create(config));
}
